#: Tables whose rows may only ever be inserted (§5.3): the audit trail.
APPEND_ONLY_TABLES: tuple[str, ...] = ("intake_events", "run_events", "human_actions")


def _create_append_only_triggers() -> None:
    """Install the ``UPDATE``/``DELETE`` guards on the audit-trail tables.

    An append-only table enforced only by convention is a claim. SQLite has no
    row-level security, so a trigger is the mechanism that makes the claim true
    for every writer - including a human at a ``sqlite3`` prompt.
    """
    for table in APPEND_ONLY_TABLES:
        for operation in ("UPDATE", "DELETE"):
            op.execute(
                # Names come from the frozen APPEND_ONLY_TABLES tuple above,
                # never from input.
                f"CREATE TRIGGER trg_{table}_no_{operation.lower()} "
                f"BEFORE {operation} ON {table} "
                f"BEGIN SELECT RAISE(ABORT, "
                f"'{table} is append-only: {operation} is not permitted'); END"
            )


def _create_outbound_approval_triggers() -> None:
    """Refuse an outbound message unless a recorded ``APPROVE`` unlocks it.

    The foreign key guarantees *some* human action exists; this trigger
    guarantees it is an approval. Without it, an EDIT or REJECT row would
    satisfy the reference and the "only an approval sends" rule would rest on
    application code alone.
    """
    for operation in ("INSERT", "UPDATE"):
        op.execute(
            f"CREATE TRIGGER trg_outbound_messages_requires_approval_{operation.lower()} "  # noqa: S608
            f"BEFORE {operation} ON outbound_messages FOR EACH ROW "
            f"WHEN COALESCE((SELECT action FROM human_actions "
            f"WHERE action_id = NEW.approval_action_id), '') <> 'APPROVE' "
            f"BEGIN SELECT RAISE(ABORT, "
            f"'outbound_messages requires a recorded APPROVE action'); END"
        )


def _drop_triggers() -> None:
    """Drop every trigger this revision created.

    The tables' own ``DROP`` would take the triggers with them; dropping them
    explicitly keeps the downgrade honest about what the upgrade installed.
    """
    for table in APPEND_ONLY_TABLES:
        for operation in ("UPDATE", "DELETE"):
            op.execute(f"DROP TRIGGER IF EXISTS trg_{table}_no_{operation.lower()}")
    for operation in ("INSERT", "UPDATE"):
        op.execute(
            f"DROP TRIGGER IF EXISTS trg_outbound_messages_requires_approval_{operation.lower()}"
        )


